1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResults = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	};
28	
29	const policyBasePremium = (items: Item[]): number =>
30	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
31	
32	const quote = (step: QuoteStep): { premium: number } => {
33	  const basePremium = policyBasePremium(step.items);
34	  const assessedPremium = basePremium + basePremium * INITIAL_ASSESSMENT_SURCHARGE;
35	
36	  return { premium: assessedPremium + PROCESSING_FEE };
37	};
38	
39	export const runScenario = (scenario: Scenario): ScenarioResults => ({
40	  results: scenario.steps.map(quote),
41	});
42

